Known-bad source:

export const MAX_UPLOAD_BYTES = 2 * 1024 * 1024;

export interface MemoryUpload {
  readonly field: string;
  readonly mimeType: string;
  readonly data: Uint8Array;
}

export class UploadFieldError extends Error {}
export class MediaTypeError extends Error {}
export class UploadSizeError extends Error {}

export function createUploadGuard(
  field: string,
  acceptedMimePrefix: string,
): (upload: MemoryUpload) => MemoryUpload {
  if (field.length === 0 || acceptedMimePrefix.length === 0) {
    throw new TypeError('Guard arguments must be non-empty');
  }
  return (upload: MemoryUpload): MemoryUpload => {
    if (upload.field !== field) throw new UploadFieldError('Unexpected upload field');
    if (!upload.mimeType.startsWith(acceptedMimePrefix)) {
      throw new MediaTypeError('Invalid media type');
    }
    if (upload.data.byteLength >= MAX_UPLOAD_BYTES) {
      throw new UploadSizeError('Upload is too large');
    }
    return { field: upload.field, mimeType: upload.mimeType, data: upload.data.slice() };
  };
}

