import { MAX_UPLOAD_BYTES, createUploadGuard, UploadFieldError, MediaTypeError, UploadSizeError } from './solution';
import type { MemoryUpload } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function throws(errorType: Function, fn: () => unknown, message: string, expectedMessage?: string): void {
  try { fn(); } catch (error) {
    if (!(error instanceof (errorType as any))) throw new Error(`${message}: wrong error`);
    if (expectedMessage !== undefined) equal((error as Error).message, expectedMessage, `${message} message`);
    return;
  }
  throw new Error(`${message}: did not throw`);
}

equal(MAX_UPLOAD_BYTES, 2 * 1024 * 1024, 'maximum size constant');
throws(TypeError, () => createUploadGuard('', 'image/'), 'empty field');
throws(TypeError, () => createUploadGuard('photo', ''), 'empty prefix');

const guard = createUploadGuard('photo', 'image/');
const inputData = new Uint8Array([1, 2, 3]);
const upload: MemoryUpload = { field: 'photo', mimeType: 'image/png', data: inputData };
const result = guard(upload);
equal(result.field, 'photo', 'field preserved');
equal(result.mimeType, 'image/png', 'mime type preserved');
assert(result !== upload, 'result object must be fresh');
assert(result.data !== inputData, 'data must be cloned');
equal(result.data.join(','), '1,2,3', 'data content cloned');
inputData[0] = 9;
equal(result.data[0], 1, 'input mutation cannot cross boundary');
result.data[1] = 8;
equal(inputData[1], 2, 'result mutation cannot cross boundary');
equal(upload.field, 'photo', 'validation does not mutate field');
equal(upload.mimeType, 'image/png', 'validation does not mutate MIME type');

const emptyResult = guard({ field: 'photo', mimeType: 'image/', data: new Uint8Array(0) });
equal(emptyResult.data.byteLength, 0, 'empty upload accepted');
const boundary = new Uint8Array(MAX_UPLOAD_BYTES);
const boundaryResult = guard({ field: 'photo', mimeType: 'image/octet-stream', data: boundary });
equal(boundaryResult.data.byteLength, MAX_UPLOAD_BYTES, 'maximum boundary accepted');
assert(boundaryResult.data !== boundary, 'boundary data cloned');

throws(UploadFieldError, () => guard({ field: 'Photo', mimeType: 'image/png', data: new Uint8Array(1) }), 'wrong field');
throws(MediaTypeError, () => guard({ field: 'photo', mimeType: 'IMAGE/png', data: new Uint8Array(1) }), 'wrong MIME', 'Invalid media type');
throws(UploadSizeError, () => guard({ field: 'photo', mimeType: 'image/png', data: new Uint8Array(MAX_UPLOAD_BYTES + 1) }), 'oversized upload');

